  "custom_fields": Array<payment_links_resource_custom_fields>;
  "custom_text": payment_links_resource_custom_text;
  "customer_creation": "always" | "if_required";
  "id": string;
  "inactive_message"?: string;
  "invoice_creation"?: Record<string, unknown>;
  "line_items"?: {
    "data": Array<item>;
    "has_more": boolean;
    "object": "list";
    "url": string;
  };
  "livemode": boolean;
  "managed_payments"?: Record<string, unknown>;
  "metadata": Record<string, string>;
  "name_collection"?: payment_links_resource_name_collection;
  "object": "payment_link";
  "on_behalf_of"?: Record<string, unknown>;
  "optional_items"?: Array<payment_links_resource_optional_item>;
  "payment_intent_data"?: Record<string, unknown>;
